/**
 * Claims generated FROM the archive, so the numbers on a page are copied out of
 * the manifest instead of typed by hand.
 *
 * The generated file is the strictest set of claims the archive passes today:
 * exact counts, exact size, every image dimension seen, the junk files it does
 * not contain. It deliberately has no `page` section — the generator has never
 * seen the page — so the author adds `page.counts`/`forbidden` by hand and the
 * numbers behind them are already pinned.
 *
 * `generateClaims` refuses an archive with integrity problems: pinning the
 * claims of a corrupt archive would make the corruption the expected state.
 */

import { compileGlob } from './glob.mjs';
import { DOC_PATTERNS, imageMismatches, nonAsciiNames, SCHEMA_VERSION } from './verify.mjs';

/** Files and folders nobody means to ship; generated as forbidden when absent. */
export const JUNK = ['__MACOSX/', '.DS_Store', 'Thumbs.db', 'desktop.ini', '.git/', '*.tmp', '~$*'];

const dimOf = (f) => (f.image && f.image.width !== null ? `${f.image.width}x${f.image.height}` : null);
const base = (p) => p.slice(p.lastIndexOf('/') + 1);
const sorted = (a) => [...a].sort();
/** "16x16" before "128x128": by width, then height, not by string. */
const bySize = (a) => [...a].sort((x, y) => {
  const [xw, xh] = x.split('x').map(Number);
  const [yw, yh] = y.split('x').map(Number);
  return xw - yw || xh - yh;
});

function rawExt(p) {
  const b = base(p);
  const dot = b.lastIndexOf('.');
  return dot > 0 ? b.slice(dot + 1) : '';
}

function imageGroups(source) {
  const byExt = new Map();
  for (const f of source.files) {
    if (!f.image || !f.ext) continue;
    if (!byExt.has(f.ext)) byExt.set(f.ext, []);
    byExt.get(f.ext).push(f);
  }
  const groups = [];
  for (const ext of sorted(byExt.keys())) {
    // Every file with this lowercase extension — images or not — so the group
    // count lines up with files.byExtension and a stray non-image `.png` shows
    // up as a dimension failure rather than vanishing from the group.
    const members = source.files.filter((f) => f.ext === ext);
    const spellings = sorted(new Set(members.map((f) => rawExt(f.path))));
    const glob = spellings.length === 1 ? `**/*.${spellings[0]}` : `**/*.{${spellings.join(',')}}`;
    const dims = members.map(dimOf);
    const group = { name: `${ext} images`, glob, count: members.length };
    if (dims.every(Boolean)) group.dimensions = bySize(new Set(dims));
    groups.push(group);
  }
  return groups;
}

export function generateClaims(source) {
  if (source.problems.length) {
    throw new Error(`refusing to generate claims from a source with integrity problems:\n  ${source.problems.join('\n  ')}`);
  }
  if (source.files.length === 0) throw new Error('refusing to generate claims from an empty source');

  const byExtension = {};
  for (const f of source.files) byExtension[f.ext] = (byExtension[f.ext] ?? 0) + 1;

  const claims = {
    schemaVersion: SCHEMA_VERSION,
    description: 'Generated by prodcheck-claims generate. Add a "page" section by hand.',
    files: {
      total: source.files.length,
      byExtension: Object.fromEntries(sorted(Object.keys(byExtension)).map((e) => [e, byExtension[e]])),
      exhaustive: true,
    },
  };
  const groups = imageGroups(source);
  if (groups.length) claims.groups = groups;
  claims.totalBytes = source.files.reduce((s, f) => s + f.size, 0);

  const docs = {};
  for (const [kind, re] of Object.entries(DOC_PATTERNS)) {
    if (source.files.some((f) => re.test(base(f.path)) && f.size > 0)) docs[kind] = true;
  }

  // Required paths: the docs found, at the exact place they ship.
  const required = source.files.filter((f) => Object.values(DOC_PATTERNS).some((re) => re.test(base(f.path))) && f.size > 0).map((f) => f.path);
  claims.paths = {};
  if (required.length) claims.paths.required = required;
  // Only the junk the archive does not already contain, so the file passes.
  const present = (g) => {
    const m = compileGlob(g);
    return source.dirs.some((d) => m.test(d, true)) || source.files.some((f) => m.test(f.path, false));
  };
  claims.paths.forbidden = JUNK.filter((g) => !present(g));
  if (claims.paths.forbidden.length === 0) delete claims.paths.forbidden;
  if (Object.keys(claims.paths).length === 0) delete claims.paths;

  if (nonAsciiNames(source).length === 0) claims.names = { asciiOnly: true };
  if (Object.keys(docs).length) claims.docs = docs;
  if (source.files.some((f) => f.image) && imageMismatches(source.files).length === 0) {
    claims.images = { contentMatchesExtension: true };
  }
  return claims;
}

const human = (n) => (n >= 1e6 ? `${(n / 1e6).toFixed(1)} MB` : n >= 1e3 ? `${(n / 1e3).toFixed(1)} KB` : `${n} B`);

/**
 * Plain sentences for the store page, every number taken from the manifest.
 * Paste them; do not retype them.
 */
export function pageFacts(source) {
  const lines = [];
  const total = source.files.reduce((s, f) => s + f.size, 0);
  lines.push(`${source.files.length} files, ${human(total)} uncompressed (${total.toLocaleString('en-US')} bytes).`);
  for (const g of imageGroups(source)) {
    const sizes = g.dimensions ? `, ${g.dimensions.join(', ')} px` : '';
    lines.push(`${g.count} ${g.name.split(' ')[0].toUpperCase()} image${g.count === 1 ? '' : 's'}${sizes}.`);
  }
  const lic = source.files.filter((f) => DOC_PATTERNS.license.test(base(f.path))).map((f) => f.path);
  if (lic.length) lines.push(`Licence: ${lic.join(', ')}.`);
  return `${lines.join('\n')}\n`;
}
